import React, { useRef, useEffect, useCallback } from 'react';
import { GameStatus, Player, Bullet, Enemy, EnemyType } from '../types';

interface Props {
  status: GameStatus;
  level: number;
  onGameOver: (score: number) => void;
  onScoreUpdate: (score: number) => void;
  onLevelUp: (nextLevel: number) => void;
}

const CANVAS_WIDTH = 450;
const CANVAS_HEIGHT = 650;
const PLAYER_SIZE = 30;
const ENEMY_SIZE = 24;
const BULLET_SIZE = 6;

const GameCanvas: React.FC<Props> = ({ status, level, onGameOver, onScoreUpdate, onLevelUp }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();

  // Game state refs (to avoid closure issues in the loop)
  const playerRef = useRef<Player>({
    x: CANVAS_WIDTH / 2 - PLAYER_SIZE / 2,
    y: CANVAS_HEIGHT - 60,
    width: PLAYER_SIZE,
    height: PLAYER_SIZE,
    speed: 5,
    lives: 3
  });

  const bulletsRef = useRef<Bullet[]>([]);
  const enemiesRef = useRef<Enemy[]>([]);
  const scoreRef = useRef(0);
  const keysRef = useRef<{ [key: string]: boolean }>({});
  const lastShotTime = useRef(0);
  const enemyMoveDir = useRef(1); // 1 for right, -1 for left
  const enemyGridOffset = useRef(0);
  const enemyDropTimer = useRef(0);

  // Initialize Enemies
  const initEnemies = useCallback((lvl: number) => {
    const rows = 5;
    const cols = 8;
    const padding = 15;
    const startX = (CANVAS_WIDTH - (cols * (ENEMY_SIZE + padding))) / 2;
    const startY = 80;

    const newEnemies: Enemy[] = [];
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        let type = EnemyType.BEE;
        let color = '#4ade80'; // Green
        let points = 50;

        if (r === 0) {
          type = EnemyType.BOSS;
          color = '#f87171'; // Red
          points = 150;
        } else if (r < 3) {
          type = EnemyType.BUTTERFLY;
          color = '#60a5fa'; // Blue
          points = 80;
        }

        newEnemies.push({
          x: startX + c * (ENEMY_SIZE + padding),
          y: startY + r * (ENEMY_SIZE + padding),
          width: ENEMY_SIZE,
          height: ENEMY_SIZE,
          startX: startX + c * (ENEMY_SIZE + padding),
          startY: startY + r * (ENEMY_SIZE + padding),
          type,
          color,
          points,
          status: 'IDLE',
          diveAngle: 0,
          diveRadius: 0
        });
      }
    }
    enemiesRef.current = newEnemies;
  }, []);

  useEffect(() => {
    if (status === GameStatus.PLAYING && enemiesRef.current.length === 0) {
      initEnemies(level);
      scoreRef.current = 0;
      playerRef.current.lives = 3;
      onScoreUpdate(0);
    }
  }, [status, level, initEnemies, onScoreUpdate]);

  // Controls
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => { keysRef.current[e.code] = true; };
    const handleKeyUp = (e: KeyboardEvent) => { keysRef.current[e.code] = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, []);

  const shoot = () => {
    const now = Date.now();
    if (now - lastShotTime.current > 300) {
      bulletsRef.current.push({
        x: playerRef.current.x + playerRef.current.width / 2 - BULLET_SIZE / 2,
        y: playerRef.current.y,
        width: BULLET_SIZE,
        height: BULLET_SIZE * 2,
        active: true
      });
      lastShotTime.current = now;
    }
  };

  const update = (ctx: HTMLCanvasElement) => {
    if (status !== GameStatus.PLAYING) return;

    // 1. Move Player
    if (keysRef.current['ArrowLeft'] && playerRef.current.x > 0) {
      playerRef.current.x -= playerRef.current.speed;
    }
    if (keysRef.current['ArrowRight'] && playerRef.current.x < CANVAS_WIDTH - playerRef.current.width) {
      playerRef.current.x += playerRef.current.speed;
    }
    if (keysRef.current['Space']) {
      shoot();
    }

    // 2. Move Bullets
    bulletsRef.current.forEach(b => {
      b.y -= 8;
      if (b.y < -20) b.active = false;
    });
    bulletsRef.current = bulletsRef.current.filter(b => b.active);

    // 3. Move Enemies (Grid)
    enemyGridOffset.current += 1 * enemyMoveDir.current;
    if (Math.abs(enemyGridOffset.current) > 40) {
      enemyMoveDir.current *= -1;
    }

    // 4. Enemy AI (Diving)
    const activeEnemies = enemiesRef.current;
    if (Math.random() < 0.005 + (level * 0.002)) {
      const idleEnemies = activeEnemies.filter(e => e.status === 'IDLE');
      if (idleEnemies.length > 0) {
        const diver = idleEnemies[Math.floor(Math.random() * idleEnemies.length)];
        diver.status = 'DIVING';
        diver.diveAngle = 0;
      }
    }

    activeEnemies.forEach(e => {
      if (e.status === 'IDLE') {
        e.x = e.startX + enemyGridOffset.current;
      } else if (e.status === 'DIVING') {
        e.y += 3 + (level * 0.5);
        e.x += Math.sin(e.diveAngle) * 5;
        e.diveAngle += 0.1;
        if (e.y > CANVAS_HEIGHT) {
          e.y = -50;
          e.status = 'RETURNING';
        }
      } else if (e.status === 'RETURNING') {
        e.y += 2;
        if (e.y >= e.startY) {
          e.status = 'IDLE';
        }
      }
    });

    // 5. Collision Detection
    bulletsRef.current.forEach(b => {
      activeEnemies.forEach(e => {
        if (
          b.x < e.x + e.width &&
          b.x + b.width > e.x &&
          b.y < e.y + e.height &&
          b.y + b.height > e.y
        ) {
          b.active = false;
          // Hit! Remove enemy
          enemiesRef.current = enemiesRef.current.filter(item => item !== e);
          scoreRef.current += e.points;
          onScoreUpdate(scoreRef.current);
        }
      });
    });

    // Player Death
    activeEnemies.forEach(e => {
      if (
        e.x < playerRef.current.x + playerRef.current.width &&
        e.x + e.width > playerRef.current.x &&
        e.y < playerRef.current.y + playerRef.current.height &&
        e.y + e.height > playerRef.current.y
      ) {
        // Simple Reset for Demo
        onGameOver(scoreRef.current);
      }
    });

    // 6. Level Up check
    if (activeEnemies.length === 0) {
      onLevelUp(level + 1);
      initEnemies(level + 1);
    }
  };

  const draw = (ctx: CanvasRenderingContext2D) => {
    ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // Starfield Background (Static for now, could be animated)
    ctx.fillStyle = 'rgba(255,255,255,0.1)';
    for(let i=0; i<50; i++) {
        const x = (i * 137) % CANVAS_WIDTH;
        const y = (i * 199 + Date.now()/10) % CANVAS_HEIGHT;
        ctx.fillRect(x, y, 1, 1);
    }

    // Draw Player
    ctx.fillStyle = '#fff';
    // Classic spaceship shape
    ctx.beginPath();
    ctx.moveTo(playerRef.current.x + playerRef.current.width / 2, playerRef.current.y);
    ctx.lineTo(playerRef.current.x + playerRef.current.width, playerRef.current.y + playerRef.current.height);
    ctx.lineTo(playerRef.current.x, playerRef.current.y + playerRef.current.height);
    ctx.closePath();
    ctx.fill();
    // Accents
    ctx.fillStyle = '#ef4444';
    ctx.fillRect(playerRef.current.x + 5, playerRef.current.y + 20, 5, 5);
    ctx.fillRect(playerRef.current.x + playerRef.current.width - 10, playerRef.current.y + 20, 5, 5);

    // Draw Bullets
    ctx.fillStyle = '#fbbf24';
    bulletsRef.current.forEach(b => {
      ctx.fillRect(b.x, b.y, b.width, b.height);
    });

    // Draw Enemies
    enemiesRef.current.forEach(e => {
      ctx.fillStyle = e.color;
      // Bee shape
      ctx.fillRect(e.x + 4, e.y, e.width - 8, e.height); // Body
      ctx.fillRect(e.x, e.y + 4, e.width, 4); // Wings

      // Eyes/Details
      ctx.fillStyle = '#000';
      ctx.fillRect(e.x + 6, e.y + 2, 2, 2);
      ctx.fillRect(e.x + e.width - 8, e.y + 2, 2, 2);
    });
  };

  const gameLoop = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    update(canvas);
    draw(ctx);
    requestRef.current = requestAnimationFrame(gameLoop);
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(gameLoop);
    return () => {
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [status, level]);

  return (
    <canvas
      ref={canvasRef}
      width={CANVAS_WIDTH}
      height={CANVAS_HEIGHT}
      className="bg-black cursor-crosshair"
    />
  );
};

export default GameCanvas;

