              className="w-16 h-16 rounded-full bg-white/10 border-2 border-cyan-500/50 flex items-center justify-center active:bg-cyan-500/30 active:scale-90 transition-all"
            >
              <ArrowLeft className="text-cyan-400" size={32} />
            </button>
            <button 
              onPointerDown={() => handleTouchStart('right')}
              onPointerUp={() => handleTouchEnd('right')}
              onPointerLeave={() => handleTouchEnd('right')}
              className="w-16 h-16 rounded-full bg-white/10 border-2 border-cyan-500/50 flex items-center justify-center active:bg-cyan-500/30 active:scale-90 transition-all"
            >
              <ArrowRight className="text-cyan-400" size={32} />
            </button>
          </div>

          <button 
            onPointerDown={() => handleTouchStart('fire')}
            onPointerUp={() => handleTouchEnd('fire')}
            onPointerLeave={() => handleTouchEnd('fire')}
            className="w-24 h-24 rounded-full bg-red-600/20 border-4 border-red-500 flex items-center justify-center active:bg-red-500 active:scale-95 transition-all shadow-[0_0_20px_rgba(239,68,68,0.4)]"
          >
            <Target className="text-white" size={40} />
          </button>
        </div>
      )}

      {/* Overlays */}
      {gameState.status === GameStatus.START && (
        <div className="absolute inset-0 bg-black/90 flex flex-col items-center justify-center z-30 backdrop-blur-sm p-6 text-center">
          <h1 className="text-4xl md:text-6xl text-cyan-400 mb-4 tracking-tighter animate-pulse">
            小蜜蜂 <span className="text-yellow-400">1980</span>
          </h1>
          <p className="text-gray-400 mb-12 max-w-md leading-relaxed tracking-wide text-xs md:text-sm">
            經典街機復刻。守護地球，消滅蜂群。
          </p>
          <button 
            onClick={startGame}
            className="flex items-center gap-3 bg-cyan-600 hover:bg-cyan-500 text-white px-10 py-5 rounded-full transition-all hover:scale-105 active:scale-95 shadow-lg shadow-cyan-900/40 font-bold text-lg"
          >
            <Play fill="white" /> 進入戰區
          </button>
          <div className="mt-12 grid grid-cols-2 gap-8 text-[10px] text-gray-500 uppercase tracking-widest">
             <div className="md:block hidden">[ 左右鍵 ] 移動</div>
             <div className="md:block hidden">[ 空白鍵 ] 發射</div>
             <div className="md:hidden block">觸控螢幕控制</div>
          </div>
        </div>
      )}

      {gameState.status === GameStatus.GAMEOVER && (
        <div className="absolute inset-0 bg-red-900/40 flex flex-col items-center justify-center z-30 backdrop-blur-md p-6">
          <div className="bg-black/95 p-8 md:p-12 rounded-2xl border-2 border-red-500 flex flex-col items-center shadow-2xl w-full max-w-sm">
            <h2 className="text-4xl md:text-5xl text-red-500 mb-6 tracking-tighter font-black">任務失敗</h2>
            <div className="text-white mb-10 flex flex-col items-center gap-2">
              <span className="text-gray-400 text-[10px] tracking-widest">FINAL SCORE</span>
              <span className="text-4xl font-bold text-yellow-400">{gameState.score}</span>
            </div>
            <button 
              onClick={startGame}
              className="w-full flex items-center justify-center gap-3 bg-red-600 hover:bg-red-500 text-white px-8 py-5 rounded-full transition-all hover:scale-105 active:scale-95 shadow-lg shadow-red-900/40 font-bold"
            >
              <RefreshCw size={20} /> 再次挑戰
            </button>
          </div>
        </div>
      )}

      {gameState.status === GameStatus.LEVEL_UP && (
        <div className="absolute inset-0 flex flex-col items-center justify-center z-30 pointer-events-none p-6 text-center">
          <div className="animate-bounce">
             <div className="text-4xl md:text-6xl text-yellow-400 tracking-[0.2em] font-black drop-shadow-2xl">LEVEL {gameState.level}</div>
             <div className="text-cyan-300 mt-4 text-sm md:text-xl font-bold tracking-widest">全軍備戰中...</div>
          </div>
        </div>
      )}

      {/* Footer */}
      <div className="hidden md:block absolute bottom-8 text-gray-700 text-[8px] tracking-[0.5em] uppercase">
        TAIWAN RETRO ARCADE SERIES &copy; 2025
      </div>
    </div>
  );
};

export default App;

import React, { useRef, useEffect, useCallback } from 'react';
import { GameStatus, Player, Bullet, Enemy, EnemyType } from '../types';

interface Props {
  status: GameStatus;
  level: number;
  onGameOver: (score: number) => void;
  onScoreUpdate: (score: number) => void;
  onLevelUp: (nextLevel: number) => void;
  touchInputs?: {
    left: boolean;
    right: boolean;
    fire: boolean;
  };
}

const CANVAS_WIDTH = 450;
const CANVAS_HEIGHT = 650;
const PLAYER_SIZE = 36; // Slightly larger for mobile visibility
const ENEMY_SIZE = 28;  // Slightly larger for mobile visibility
const BULLET_SIZE = 6;

const GameCanvas: React.FC<Props> = ({ status, level, onGameOver, onScoreUpdate, onLevelUp, touchInputs }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();

  const playerRef = useRef<Player>({
    x: CANVAS_WIDTH / 2 - PLAYER_SIZE / 2,
    y: CANVAS_HEIGHT - 80,
    width: PLAYER_SIZE,
    height: PLAYER_SIZE,
    speed: 6, // Slightly faster for snappier feel
    lives: 3
  });

  const bulletsRef = useRef<Bullet[]>([]);
  const enemiesRef = useRef<Enemy[]>([]);
  const scoreRef = useRef(0);
  const keysRef = useRef<{ [key: string]: boolean }>({});
  const lastShotTime = useRef(0);
  const enemyMoveDir = useRef(1);
  const enemyGridOffset = useRef(0);

  const initEnemies = useCallback((lvl: number) => {
    const rows = 5;
    const cols = 7; // Slightly fewer columns for better spacing on small screens
    const padding = 20;
    const startX = (CANVAS_WIDTH - (cols * (ENEMY_SIZE + padding))) / 2;
    const startY = 80;

    const newEnemies: Enemy[] = [];
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        let type = EnemyType.BEE;
        let color = '#4ade80';
        let points = 50;

        if (r === 0) {
          type = EnemyType.BOSS;
          color = '#f87171';
          points = 150;
        } else if (r < 3) {
          type = EnemyType.BUTTERFLY;
          color = '#60a5fa';
          points = 80;
        }

        newEnemies.push({
          x: startX + c * (ENEMY_SIZE + padding),
          y: startY + r * (ENEMY_SIZE + padding),
          width: ENEMY_SIZE,
          height: ENEMY_SIZE,
          startX: startX + c * (ENEMY_SIZE + padding),
          startY: startY + r * (ENEMY_SIZE + padding),
          type,
          color,
          points,
          status: 'IDLE',
          diveAngle: 0,
          diveRadius: 0
        });
      }
    }
    enemiesRef.current = newEnemies;
  }, []);

  useEffect(() => {
    if (status === GameStatus.PLAYING && enemiesRef.current.length === 0) {
      initEnemies(level);
      scoreRef.current = 0;
      playerRef.current.lives = 3;
      onScoreUpdate(0);
    }
  }, [status, level, initEnemies, onScoreUpdate]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => { keysRef.current[e.code] = true; };
    const handleKeyUp = (e: KeyboardEvent) => { keysRef.current[e.code] = false; };
    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, []);

  const shoot = () => {
    const now = Date.now();
    if (now - lastShotTime.current > 250) { // Slightly faster fire rate
      bulletsRef.current.push({
        x: playerRef.current.x + playerRef.current.width / 2 - BULLET_SIZE / 2,
        y: playerRef.current.y,
        width: BULLET_SIZE,
        height: BULLET_SIZE * 3, // Taller bullets for laser look
        active: true
      });
      lastShotTime.current = now;
    }
  };

  const update = () => {
    if (status !== GameStatus.PLAYING) return;

    // Movement: Keyboard + Touch
    const moveLeft = keysRef.current['ArrowLeft'] || touchInputs?.left;
    const moveRight = keysRef.current['ArrowRight'] || touchInputs?.right;
    const isFiring = keysRef.current['Space'] || touchInputs?.fire;

    if (moveLeft && playerRef.current.x > 0) {
      playerRef.current.x -= playerRef.current.speed;
    }
    if (moveRight && playerRef.current.x < CANVAS_WIDTH - playerRef.current.width) {
      playerRef.current.x += playerRef.current.speed;
    }
    if (isFiring) {
      shoot();
    }

    bulletsRef.current.forEach(b => {
      b.y -= 10;
      if (b.y < -30) b.active = false;
    });
    bulletsRef.current = bulletsRef.current.filter(b => b.active);

    enemyGridOffset.current += 1 * enemyMoveDir.current;
    if (Math.abs(enemyGridOffset.current) > 30) {
      enemyMoveDir.current *= -1;
    }

    const activeEnemies = enemiesRef.current;
    if (Math.random() < 0.006 + (level * 0.002)) {
      const idleEnemies = activeEnemies.filter(e => e.status === 'IDLE');
      if (idleEnemies.length > 0) {
        const diver = idleEnemies[Math.floor(Math.random() * idleEnemies.length)];
        diver.status = 'DIVING';
        diver.diveAngle = 0;
      }
    }

    activeEnemies.forEach(e => {
      if (e.status === 'IDLE') {
        e.x = e.startX + enemyGridOffset.current;
      } else if (e.status === 'DIVING') {
        e.y += 4 + (level * 0.6);
        e.x += Math.sin(e.diveAngle) * 6;
        e.diveAngle += 0.12;
        if (e.y > CANVAS_HEIGHT) {
          e.y = -50;
          e.status = 'RETURNING';
        }
      } else if (e.status === 'RETURNING') {
        e.y += 3;
        if (e.y >= e.startY) {
          e.status = 'IDLE';
        }
      }
    });

    bulletsRef.current.forEach(b => {
      activeEnemies.forEach(e => {
        if (
          b.x < e.x + e.width &&
          b.x + b.width > e.x &&
          b.y < e.y + e.height &&
          b.y + b.height > e.y
        ) {
          b.active = false;
          enemiesRef.current = enemiesRef.current.filter(item => item !== e);
          scoreRef.current += e.points;
          onScoreUpdate(scoreRef.current);
        }
      });
    });

    activeEnemies.forEach(e => {
      if (
        e.x < playerRef.current.x + playerRef.current.width * 0.8 &&
        e.x + e.width > playerRef.current.x + playerRef.current.width * 0.2 &&
        e.y < playerRef.current.y + playerRef.current.height * 0.8 &&
        e.y + e.height > playerRef.current.y + playerRef.current.height * 0.2
      ) {
        onGameOver(scoreRef.current);
      }
    });

    if (activeEnemies.length === 0) {
      onLevelUp(level + 1);
      initEnemies(level + 1);
    }
  };

  const draw = (ctx: CanvasRenderingContext2D) => {
    ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // Stars
    ctx.fillStyle = 'rgba(255,255,255,0.2)';
    for(let i=0; i<40; i++) {
        const x = (i * 137) % CANVAS_WIDTH;
        const y = (i * 199 + Date.now()/8) % CANVAS_HEIGHT;
        ctx.fillRect(x, y, 2, 2);
    }

    // Player
    ctx.fillStyle = '#fff';
    ctx.beginPath();
    ctx.moveTo(playerRef.current.x + playerRef.current.width / 2, playerRef.current.y);
    ctx.lineTo(playerRef.current.x + playerRef.current.width, playerRef.current.y + playerRef.current.height);
    ctx.lineTo(playerRef.current.x, playerRef.current.y + playerRef.current.height);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = '#ef4444';
    ctx.fillRect(playerRef.current.x + 2, playerRef.current.y + playerRef.current.height - 10, 6, 6);
    ctx.fillRect(playerRef.current.x + playerRef.current.width - 8, playerRef.current.y + playerRef.current.height - 10, 6, 6);

    // Bullets
    bulletsRef.current.forEach(b => {
      ctx.fillStyle = '#fbbf24';
      ctx.fillRect(b.x, b.y, b.width, b.height);
      ctx.fillStyle = '#fff';
      ctx.fillRect(b.x + 1, b.y + 2, b.width - 2, b.height - 4);
    });

    // Enemies
    enemiesRef.current.forEach(e => {
      ctx.shadowBlur = 10;
      ctx.shadowColor = e.color;
      ctx.fillStyle = e.color;

      const wingOffset = Math.sin(Date.now() / 150) * 4;

      ctx.fillRect(e.x + 6, e.y, e.width - 12, e.height); // Body
      ctx.fillRect(e.x, e.y + 4 + wingOffset, e.width, 6); // Wings

      ctx.fillStyle = '#fff';
      ctx.fillRect(e.x + 8, e.y + 4, 3, 3);
      ctx.fillRect(e.x + e.width - 11, e.y + 4, 3, 3);
      ctx.shadowBlur = 0;
    });
  };

  const gameLoop = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    update();
    draw(ctx);
    requestRef.current = requestAnimationFrame(gameLoop);
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(gameLoop);
    return () => {
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [status, level, touchInputs]);

  return (
    <canvas
      ref={canvasRef}
      width={CANVAS_WIDTH}
      height={CANVAS_HEIGHT}
      className="bg-black block mx-auto h-full w-full object-contain"
    />
  );
};

export default GameCanvas;
